/* MA PAYE.0: extended preparation and draft payslips. Keeps mapaye-demo-v1. */
const euroFmt=n=>Number(n).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
const normalRender=render,normalCSV=csv;let selectedPerson='';
db.bulletins=db.bulletins||[];db.profileHistory=db.profileHistory||[];
const field=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;
const num=(name,label,value='0',step='.01')=>field(name,label,value,'number',`min="0" max="10000000" step="${step}" required`);
const selectField=(name,label,value,options)=>`<label>${label}<select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const section=(title,html,open=true)=>`<details ${open?'open':''}><summary>${title}</summary><div class="fields">${html}</div></details>`;
const formActions=`<div class="actions sticky"><button type="button" class="btn secondary" onclick="document.querySelector('dialog').close()">Annuler</button><button class="btn">Enregistrer</button></div>`;
function extendedForm(html,callback){$('#form').oninput=null;$('#form').onchange=null;$('#form').innerHTML=html+`<p id="formError" class="error" role="alert"></p>`+formActions;$('#form').onsubmit=e=>{e.preventDefault();try{const result=callback(new FormData(e.target));if(result===false)return;$('#modal').close();render();toast('Enregistré dans ce navigateur.')}catch(err){$('#formError').textContent=err.message}};$('#modal').showModal();}
function remember(reason){db.profileHistory.push({at:new Date().toISOString(),reason});if(db.profileHistory.length>500)db.profileHistory.shift();}
function invalidate(personId){Object.keys(db.vars).forEach(k=>{if(k.startsWith(company+'|')&&k.endsWith('|'+personId))db.vars[k].status='À vérifier'});}
function personDefaults(p){return{...p,contract:p.contract==='Apprentissage'?'CDD':p.contract,scheme:p.scheme||(p.contract==='Apprentissage'?'Apprentissage':'Aucun'),hours:p.hours??151.67};}
employee=function(id){let original=db.people.find(p=>p.id===id),p=personDefaults(original||{name:'',job:'',contract:'CDI',hours:151.67});extendedForm(`<h2>${id?'Fiche salarié et contrat':'Nouveau salarié de test'}</h2><p>Informations durables. Les variables du mois se saisissent dans Préparation paie.</p>`+
section('1. Identité et emploi',field('name','Nom complet',p.name,'text','required maxlength="100"')+field('matricule','Matricule',p.matricule)+field('birthDate','Date de naissance',p.birthDate,'date')+field('address','Adresse — numéro et voie',p.address)+field('postalCode','Code postal',p.postalCode,'text','maxlength="20" autocomplete="postal-code"')+field('city','Ville',p.city,'text','maxlength="100" autocomplete="address-level2"')+field('job','Emploi / poste',p.job,'text','required maxlength="100"')+selectField('category','Catégorie',p.category||'Employé',['Ouvrier','Employé','ETAM','Cadre','Autre'])+field('classification','Niveau / échelon / coefficient',p.classification)+conventionPicker(p.idcc,'employee'))+
section('2. Contrat et dates',selectField('contract','Nature du contrat',p.contract,EmploymentCatalog.options(EmploymentCatalog.natures,p.contract))+selectField('scheme','Dispositif du contrat',p.scheme,EmploymentCatalog.options(EmploymentCatalog.schemes,p.scheme))+selectField('contractVariant','Type particulier / cadre d’emploi',p.contractVariant||'Droit commun',EmploymentCatalog.options(EmploymentCatalog.variants,p.contractVariant))+selectField('workOrganization','Organisation du travail',p.workOrganization||'Horaire habituel',['Horaire habituel','Temps de travail annualisé — accord à vérifier','Intermittence — cadre à vérifier','Autre'])+selectField('insertionPath','Parcours d’insertion associé',p.insertionPath||'Aucun',['Aucun','Parcours d’insertion avec apprentissage','Parcours d’insertion avec professionnalisation','Autre — à préciser'])+field('contractContext','Accord / éligibilité / précisions du dispositif',p.contractContext)+selectField('apprenticeAdaptation','Aménagement du parcours d’apprentissage',p.apprenticeAdaptation||'Non renseigné',['Non renseigné','Aucun','Parcours aménagé — conditions à vérifier'])+field('contractId','Référence du contrat',p.contractId)+field('startDate','Date de début',p.startDate,'date')+field('endDate','Fin prévue (si applicable)',p.endDate,'date')+selectField('cddReason','Motif de recours au CDD',p.cddReason||'À renseigner',EmploymentCatalog.options(EmploymentCatalog.reasons,p.cddReason))+field('cddReasonDetails','Précisions et pièces justifiant le recours au CDD',p.cddReasonDetails)+selectField('cddTermType','Terme du CDD',p.cddTermType||'À définir',['À définir','Terme précis','Sans terme précis — durée minimale à renseigner'])+field('cddMinimumEndDate','Fin de durée minimale (CDD sans terme précis)',p.cddMinimumEndDate,'date')+field('trialEnd','Fin de période d’essai',p.trialEnd,'date')+field('seniorityDate','Ancienneté retenue depuis',p.seniorityDate,'date')+`<div class="wide employee-subblock"><h3>Fin de CDD — si concerné</h3><div class="fields">`+field('actualEndDate','Date de fin réelle du contrat',p.actualEndDate,'date')+selectField('cddEndReason','Motif de fin de CDD',p.cddEndReason||'À définir',p.cddEndReason&&!EmployeeFields.cddEndReasons.includes(p.cddEndReason)?[...EmployeeFields.cddEndReasons,p.cddEndReason]:EmployeeFields.cddEndReasons)+field('cddEndDetails','Précisions sur la fin du CDD',p.cddEndDetails)+field('cddEndDocument','Pièce / référence justifiant la fin du CDD',p.cddEndDocument)+`<p class="wide muted">Le motif de fin est distinct du motif de recours au CDD. Le choix doit correspondre à la situation et aux pièces du dossier ; il ne calcule pas automatiquement les indemnités et ne transmet aucune déclaration.</p></div></div>`)+
`<p class="muted">Temps plein / temps partiel : choix indépendant dans Temps et rémunération. Les dispositifs, secteurs autorisés et conditions d’éligibilité sont à vérifier ; leur sélection ne déclenche pas d’exonération ou d’aide automatique. Un besoin temporaire générique ne suffit pas à justifier un CDD.</p>`+section('3. Temps et rémunération',selectField('workMode','Modalité de travail',p.workMode||'Temps plein',['Temps plein','Temps partiel','Forfait jours','Autre'])+num('weeklyHours','Heures hebdomadaires de référence',p.weeklyHours??35)+num('hours','Heures mensuelles de référence',p.hours)+field('monthlyBase','Salaire mensuel de base (€)',p.monthlyBase,'number','min="0" max="10000000" step=".01"')+field('hourlyRate','Taux horaire pour majorations (€)',p.hourlyRate,'number','min="0" max="100000" step=".0001"')+field('structuralHours','HS structurelles comprises au contrat',p.structuralHours)+field('salaryEffective','Date d’effet du salaire',p.salaryEffective,'date')+field('schedule','Planning / répartition habituelle',p.schedule))+
section('4. Transport domicile-travail',selectField('transportMode','Mode de transport',p.transportMode||'À définir',p.transportMode&&!EmployeeFields.transportModes.includes(p.transportMode)?[...EmployeeFields.transportModes,p.transportMode]:EmployeeFields.transportModes)+selectField('transportSubscription','Abonnement de transport',p.transportSubscription||'À définir',EmploymentCatalog.options(EmploymentCatalog.subscriptions,p.transportSubscription))+selectField('transportFrequency','Périodicité de l’abonnement',p.transportFrequency||'À définir',['À définir','Hebdomadaire','Mensuel','Annuel','Autre'])+field('transportNetwork','Réseau / formule / zones / trajet',p.transportNetwork)+field('transportMonthlyCost','Coût mensuel de référence du transport (€)',p.transportMonthlyCost,'number','min="0" max="100000" step=".01"')+field('transportReimbursementPercent','Taux de prise en charge transport urbain (%)',50,'number','readonly')+field('transportValidFrom','Abonnement / prise en charge valable du',p.transportValidFrom,'date')+field('transportValidUntil','Abonnement / prise en charge valable au',p.transportValidUntil,'date')+selectField('transportProofStatus','Justificatif de transport',p.transportProofStatus||'À demander',['À demander','Reçu','À vérifier','Non applicable'])+field('transportNotes','Précisions / référence du justificatif transport',p.transportNotes)+`<p class="wide muted">Cette fiche conserve les références habituelles. Le montant remboursé reste à vérifier chaque mois dans Préparation paie. Le coût est repris par défaut pour un nouveau mois, avec une prise en charge de 50 %. Vérifiez le justificatif et les situations particulières dans la préparation. Pour un abonnement annuel ou hebdomadaire, renseignez le coût imputable au mois et vérifiez sa périodicité ; aucun tarif ni conversion automatique n’est imposé. Tickets à l’unité, cartes de réduction et paiements à l’usage ne sont pas assimilés automatiquement à un abonnement éligible. Les déplacements et paniers BTP restent des rubriques séparées.</p>`)+
section('5. Apprentissage — si concerné',field('cfa','CFA / organisme',p.cfa)+field('diploma','Diplôme / titre préparé',p.diploma)+selectField('apprenticeYear','Année du cycle',p.apprenticeYear||'À définir',['À définir','1','2','3','Autre'])+field('apprenticePercent','Pourcentage applicable (à valider)',p.apprenticePercent,'number','min="0" max="200" step=".01"')+field('apprenticeReference','Base de référence et justificatif',p.apprenticeReference),false)+
section('6. Organismes et paramètres à vérifier',field('socialRegime','Régime social',p.socialRegime)+field('retirement','Retraite complémentaire',p.retirement)+field('mutual','Mutuelle / option / dispense',p.mutual)+field('provident','Prévoyance',p.provident)+field('cibtp','Caisse CIBTP / affiliation',p.cibtp)+field('pasReference','Référence du taux PAS (test)',p.pasReference)+field('pasDate','Date de réception du taux (test)',p.pasDate,'date')+field('notes','Notes et pièces à demander',p.notes),false)+`<p class="muted">NIR, RIB et pièces sensibles ne sont pas collectés dans cette démonstration. Les paramètres réglementaires ne sont pas calculés automatiquement.</p>`,f=>{
const val=Object.fromEntries(f);EmployeeFields.validate(val);val.name=val.name.trim();val.job=val.job.trim();if(!val.name||!val.job)throw Error('Nom et poste requis.');if(val.endDate&&val.startDate&&val.endDate<val.startDate)throw Error('La fin prévue précède le début du contrat.');val.hours=Number(val.hours);if(id){db.profileHistory.push({at:new Date().toISOString(),person:id,before:structuredClone(original)});Object.assign(original,val);invalidate(id);}else db.people.push({...val,id:crypto.randomUUID(),company});if(!save())throw Error('Enregistrement impossible. Téléchargez une sauvegarde.');});};
function companyEdit(){const c=db.companies.find(c=>c.id===company);extendedForm(`<h2>Paramètres de l’entreprise</h2>`+section('Identité',field('name','Nom affiché',c.name,'text','required')+field('sector','Secteur d’activité',c.sector,'text','required')+field('address','Adresse de test',c.address)+field('siret','SIRET de test',c.siret)+field('ape','Code APE',c.ape))+section('Cadre de la paie',field('idcc','Convention collective / IDCC',c.idcc)+field('agreements','Accords / règles à vérifier',c.agreements)+field('cibtp','Caisse de congés si applicable',c.cibtp)+field('paymentDate','Date de paiement de test',c.paymentDate,'date')+field('organisms','Organismes et affiliations',c.organisms))+`<p class="muted">Les taux propres, barèmes et habilitations restent à valider avant production réelle.</p>`,f=>{remember('Paramètres entreprise modifiés');Object.assign(c,Object.fromEntries(f));db.people.filter(p=>p.company===company).forEach(p=>invalidate(p.id));save();});}
function richVar(p){let v=db.vars[vkey(p)]||{};let defaults={hours:p.hours??151.67,bonus:'0',status:'À vérifier',base:p.monthlyBase??'',hourlyRate:p.hourlyRate??'',extra25:'0',extra50:'0',extra100:'0',extraOther:'0',otherPercent:'0',hcHours:'0',hcPercent:'0',nightPremium:'0',sundayPremium:'0',holidayPremium:'0',absenceHours:'0',absenceDeduction:'0',absenceType:'Aucune',absenceStart:'',absenceEnd:'',absenceNotes:'',cpDays:'0',cpPaid:'0',ijss:'0',subrogation:'Non',mealQty:'0',mealUnit:'0',mealTaxable:'0',trip:'0',tripTaxable:'0',transportBtp:'0',transportBtpTaxable:'0',grandTravel:'0',grandTaxable:'0',navigoPrice:p.transportMonthlyCost||'0',navigoPercent:'50',transportEligibility:'100',ceiling:'4005',csgExtra:'',cpMode:'Manuel',cpReference:'',cpRights:'',cpUnit:'Ouvrables',cpMaintainReference:'',cpLeaveHours:'',cpActualHours:'',cpBaseIncludesLeave:'Oui',otherExpenses:'0',advantages:'0',advance:'0',otherDeduction:'0',taxableNet:'',socialNet:'',pasRate:'',notes:'',rows:[],source:'',exitDate:'',exitReason:''};return autoVariables({...defaults,...v,baseMode:v.baseMode||'Mensuel',monthlySalary:v.monthlySalary??v.base??p.monthlyBase??'',navigoPercent:'50'});}


function applyLeave(v){if(!v.cpMode||v.cpMode==='Manuel')return {...v,cpAutoDeduction:'0',cpTenth:'',cpMaintenance:'',cpMethod:''};v={...v,cpPaid:'0',cpAutoDeduction:'0',cpTenth:'',cpMaintenance:'',cpMethod:''};if(v.cpMode==='Caisse CIBTP')return v;if(Number(v.cpDays||0)===0)return v;if(!v.cpMaintainReference||!v.cpActualHours||v.cpLeaveHours==='')return v;const maintenance=PayrollTest.fractionAmount(v.cpMaintainReference,v.cpLeaveHours,v.cpActualHours);if(v.cpBaseIncludesLeave==='Oui')v.cpAutoDeduction=maintenance.toFixed(2);if(v.cpMode==='Employeur — plus favorable'&&v.cpReference!==''&&v.cpRights!==''){const cp=PayrollTest.leaveComparison(v.cpReference,v.cpRights,v.cpDays,maintenance);v.cpPaid=cp.favorable.toFixed(2);v.cpTenth=cp.tenth.toFixed(2);v.cpMaintenance=cp.maintenance.toFixed(2);v.cpMethod=cp.method;}return v;}
function leaveReady(v){if(v.cpMode&&v.cpMode==='Employeur — plus favorable'&&Number(v.cpDays)>0){if(!v.cpActualHours||v.cpLeaveHours===''||v.cpMaintainReference==='')throw Error('Complétez le salaire et les heures de référence des congés.');if(Number(v.cpLeaveHours)>Number(v.cpActualHours))throw Error('Les heures de congé dépassent les heures du mois.');if(v.cpMode==='Employeur — plus favorable'&&(v.cpReference===''||!Number(v.cpRights)))throw Error('Complétez la rémunération de référence et les droits acquis pour comparer les congés.');}}
function autoVariables(v){v={...v,navigoPercent:'50'};v=applyLeave(v);v.base=v.baseMode==='Horaire'?PayrollTest.quantityAmount(v.hours||0,v.hourlyRate||0).toFixed(2):v.monthlySalary;v.mealTotal=PayrollTest.quantityAmount(v.mealQty||0,v.mealUnit||0).toFixed(2);const eligible=Number(v.transportEligibility??100);if(!Number.isFinite(eligible)||eligible<0||eligible>100)throw Error('La part éligible du transport doit être comprise entre 0 et 100 %.');v.urbanTransport=PayrollTest.percentageAmount(v.navigoPrice||0,(eligible/2).toFixed(4)).toFixed(2);return v;}
function grossPreview(v){if(v.base==='')throw Error('Salaire de base à compléter');leaveReady(v);return PayrollTest.calculate({...engineInput(v),rows:[],taxableNet:'0',socialNet:'',pasRate:'0',advance:'0',otherDeduction:'0'}).gross;}
function autoSummary(v){try{return euroFmt(grossPreview(v))}catch{return 'À compléter'}}
function refreshCalculations(){const form=$('#form');if(!form.querySelector('[name=baseMode]'))return;try{const v=autoVariables(Object.fromEntries(new FormData(form)));for(const k of ['base','mealTotal','urbanTransport'])form.elements[k].value=v[k]??'';form.elements.monthlySalary.readOnly=v.baseMode==='Horaire';form.elements.cpPaid.readOnly=v.cpMode!=='Manuel';form.elements.cpPaid.value=v.cpPaid;$('#leaveLive').textContent=v.cpMode==='Caisse CIBTP'?'Paiement par la caisse : aucune retenue automatique sur salaire et aucune indemnité ajoutée par l’employeur.':v.cpMethod?`Dixième ${euroFmt(v.cpTenth)} / maintien ${euroFmt(v.cpMaintenance)} → ${v.cpMethod} : ${euroFmt(v.cpPaid)}.`:'Complétez les bases pour comparer. Mode manuel : montant conservé.';$('#grossLive').textContent=autoSummary(v);$('#calculationError').textContent='';try{const full=readVariableForm(new FormData(form));const result=PayrollTest.calculate({...engineInput(full),taxableNet:'0',pasRate:'0',socialNet:'',advance:'0',otherDeduction:'0'});$('#cotLive').textContent=`Cotisations calculées : salarié ${euroFmt(result.employee)} · employeur ${euroFmt(result.employer)}. Avant allègements et paramètres manquants.`;form.querySelectorAll('.cot-row').forEach((node,i)=>{let out=node.querySelector('output');if(!out){out=document.createElement('output');out.className='wide';node.appendChild(out)}out.textContent=`Assiette ${euroFmt(result.rows[i].base)} · salarié ${euroFmt(result.rows[i].employee)} · employeur ${euroFmt(result.rows[i].employer)}`});}catch(err){$('#cotLive').textContent='Calcul des cotisations à compléter : '+err.message;form.querySelectorAll('.cot-row output').forEach(n=>n.remove());}}catch(e){$('#grossLive').textContent='À vérifier';$('#calculationError').textContent=e.message;}}
function variableMarkup(p){let v=richVar(p);return `<h2>Préparation · ${esc(p.name)}</h2><p>${esc(period())} · ${esc(p.contract)}${p.scheme&&p.scheme!=='Aucun'?' · '+esc(p.scheme):''}</p>`+
section('1. Salaire, heures et majorations',selectField('baseMode','Calcul du salaire de base',v.baseMode,['Mensuel','Horaire'])+field('monthlySalary','Salaire mensuel contractuel (€)',v.monthlySalary,'number','min="0" step=".01"')+field('base','Salaire de base calculé (€)',v.base,'number','readonly')+num('hours','Heures normales (base du calcul en mode Horaire)',v.hours)+field('hourlyRate','Taux horaire des heures majorées (€)',v.hourlyRate,'number','min="0" max="100000" step=".0001"')+num('extra25','HS à +25 % — nombre d’heures',v.extra25)+num('extra50','HS à +50 % — nombre d’heures',v.extra50)+num('extra100','HS à +100 % — nombre d’heures',v.extra100)+num('extraOther','HS à un autre taux — heures',v.extraOther)+num('otherPercent','Autre majoration (%)',v.otherPercent)+num('hcHours','Heures complémentaires — heures',v.hcHours)+num('hcPercent','Majoration heures complémentaires (%)',v.hcPercent)+`<p class="wide muted">Mode Mensuel : salaire contractuel conservé ; mode Horaire : heures normales × taux horaire. Le brut total est actualisé avec les heures majorées, primes, parts soumises et retenues saisies. Les HS structurelles déjà payées doivent être exclues des ajouts. Décompte hebdomadaire et droit aux majorations à contrôler ; +100 % ne signifie pas automatiquement « dimanche ».</p>`)+
section('2. Primes et absences',num('bonus','Autres primes brutes (€)',v.bonus)+num('nightPremium','Prime de nuit brute (€)',v.nightPremium)+num('sundayPremium','Prime de dimanche brute (€)',v.sundayPremium)+num('holidayPremium','Prime de jour férié brute (€)',v.holidayPremium)+selectField('absenceType','Nature d’absence',v.absenceType,['Aucune','Congés payés','Maladie','AT / MP','Sans solde','Activité partielle','Intempéries','Autre'])+field('absenceStart','Absence du',v.absenceStart,'date')+field('absenceEnd','Absence au',v.absenceEnd,'date')+num('absenceHours','Heures d’absence (information)',v.absenceHours)+num('absenceDeduction','Retenue brute calculée manuellement (€)',v.absenceDeduction)+num('cpDays','Congés pris ce mois (jours)',v.cpDays)+num('cpPaid','Indemnité / maintien brut à ajouter (€)',v.cpPaid)+selectField('cpMode','Paiement des congés payés',v.cpMode||'Manuel',['Manuel','Employeur — plus favorable','Caisse CIBTP'])+selectField('cpUnit','Unité des jours pris et acquis',v.cpUnit||'Ouvrables',['Ouvrables','Ouvrés'])+field('cpReference','Brut de la période de référence éligible au dixième (€)',v.cpReference,'number','min="0" step=".01"')+field('cpRights','Jours acquis correspondant à cette référence',v.cpRights,'number','min="0" step=".01"')+field('cpMaintainReference','Salaire qui aurait été perçu sur le mois (€)',v.cpMaintainReference,'number','min="0" step=".01"')+field('cpLeaveHours','Heures correspondant aux congés pris',v.cpLeaveHours,'number','min="0" step=".01"')+field('cpActualHours','Heures réelles de travail prévues sur le mois',v.cpActualHours,'number','min="0" step=".01"')+selectField('cpBaseIncludesLeave','La base saisie comprend-elle déjà le salaire des jours de congé ?',v.cpBaseIncludesLeave||'Oui',['Oui','Non'])+`<p class="wide notice" id="leaveLive" aria-live="polite"></p><p class="wide muted">Le dixième est proratisé aux jours pris / droits acquis, dans la même unité. Le maintien est calculé selon les heures réelles du mois. Si la base inclut les jours de congé, leur retenue est déduite automatiquement avant d’ajouter l’indemnité. Ne la saisissez pas une seconde fois dans la retenue manuelle. Mode CIBTP : aucune retenue automatique sur salaire et aucune indemnité ajoutée par l’employeur. Le règlement des congés est suivi auprès de la caisse. Les éventuelles autres absences restent des saisies distinctes.</p>`+num('ijss','IJSS suivies (information uniquement, €)',v.ijss)+selectField('subrogation','Subrogation',v.subrogation,['Non','Oui','À vérifier'])+field('absenceNotes','Méthode de retenue / maintien / justificatif',v.absenceNotes)+`<p class="wide muted">Les droits et rémunérations de référence sont fournis par l’utilisateur ; le moteur ne détermine pas les IJSS, carences, maintien ou activité partielle. Une absence ou des IJSS nécessite un contrôle spécifique avant tout usage réel.</p>`)+
section('3. Paniers BTP, frais et déplacements',num('mealQty','Paniers / repas — nombre',v.mealQty)+num('mealUnit','Montant d’un panier (€)',v.mealUnit)+field('mealTotal','Total des paniers calculé (€)',v.mealTotal,'number','readonly')+num('mealTaxable','Total paniers soumis aux cotisations (€)',v.mealTaxable)+num('trip','Indemnité de trajet BTP — total (€)',v.trip)+num('tripTaxable','Dont trajet soumis (€)',v.tripTaxable)+num('transportBtp','Indemnité de transport BTP — total (€)',v.transportBtp)+num('transportBtpTaxable','Dont transport BTP soumis (€)',v.transportBtpTaxable)+num('grandTravel','Grands déplacements — total (€)',v.grandTravel)+num('grandTaxable','Dont grands déplacements soumis (€)',v.grandTaxable)+num('navigoPrice','Abonnement transport / Navigo (€)',v.navigoPrice)+field('navigoPercent','Prise en charge transport urbain (%)',50,'number','readonly')+num('transportEligibility','Part éligible de l’abonnement (%) — cas général 100',v.transportEligibility??100)+field('urbanTransport','Transport urbain remboursé, calculé (€)',v.urbanTransport,'number','readonly')+`<div class="wide"><button type="button" class="btn secondary" onclick="document.querySelector('[name=navigoPrice]').value=this.dataset.price;refreshCalculations()" data-price="${esc(p.transportMonthlyCost||0)}">Reprendre le prix de la fiche salarié (${euroFmt(p.transportMonthlyCost||0)})</button><p class="muted">Abonnement éligible × 50 %. Part éligible à adapter sur justificatif en cas particulier ; aucun ticket unitaire. Le transport BTP reste séparé.</p></div>`+num('otherExpenses','Autres frais à rembourser (€)',v.otherExpenses)+`<p class="wide muted">La ventilation soumise/non soumise est saisie et reste à justifier. Le barème conventionnel payé et la limite sociale d’exonération sont distincts. Montants à zéro à confirmer.</p>`)+
section('4. Avantages et retenues',num('advantages','Avantages en nature — valeur (€)',v.advantages)+num('advance','Acompte déjà versé (€)',v.advance)+num('otherDeduction','Autres retenues nettes justifiées (€)',v.otherDeduction)+field('exitDate','Date de sortie si concerné',v.exitDate,'date')+field('exitReason','Motif / indemnités de sortie à vérifier',v.exitReason)+`<p class="wide muted">L’avantage en nature est ajouté au brut puis déduit du net. Les indemnités de rupture et saisies ne sont pas calculées automatiquement.</p>`,false)+
section('5. Cotisations — paramètres de test',`<div class="wide"><p>Les montants se calculent sur le brut avec l’assiette choisie. Références BTP 2026 : régime général, hors apprentissage et régimes particuliers. Taux et assiettes restent à vérifier selon le contrat et l’entreprise.</p>${btpCotControls(v,p)}<div id="cotRows">${v.rows.map(rowMarkup).join('')}</div><button type="button" class="btn secondary" onclick="addCotRow()">+ Ligne de cotisation</button></div>`,false)+
section('6. Nets et prélèvement à la source — test',field('taxableNet','Net imposable fourni pour le test (€)',v.taxableNet,'number','min="0" max="10000000" step=".01"')+field('socialNet','Montant net social fourni pour le test (€)',v.socialNet,'number','min="0" max="10000000" step=".01"')+field('pasRate','Taux PAS fourni pour le test (%)',v.pasRate,'number','min="0" max="100" step=".0001"')+`<p class="wide muted">Net imposable et montant net social ne sont pas encore déterminés réglementairement. Ce sont des valeurs manuelles de test, jamais un pourcentage automatique du brut.</p>`,false)+
section('7. Justificatifs et validation',field('source','Relevé d’heures / pièce / règle de majoration',v.source)+field('notes','Points à vérifier et pièces manquantes',v.notes)+selectField('status','État des variables (hors conformité)',v.status,['À vérifier','Validé']))+`<p class="muted">Les champs vides restent à compléter. La validation des variables ne certifie pas la conformité du bulletin.</p>`;}
function rowMarkup(r={label:'',baseMode:'gross',base:'0',employeeRate:'0',employerRate:'0'}){return `<div class="cot-row">${field('cotLabel','Libellé',r.label,'text','maxlength="100"')}${selectField('cotBaseMode','Assiette',r.baseMode,['gross','manual','t1','t2','cap4','cap8','csg'])}${num('cotBase','Assiette manuelle (€)',r.base)}${num('cotEmployee','Taux salarié (%)',r.employeeRate,'.0001')}${num('cotEmployer','Taux employeur (%)',r.employerRate,'.0001')}<button type="button" class="btn secondary" onclick="this.closest('.cot-row').remove();refreshCalculations()">Retirer</button></div>`;}
function addCotRow(){$('#cotRows').insertAdjacentHTML('beforeend',rowMarkup());refreshCalculations();}
function readVariableForm(f){let v=autoVariables(Object.fromEntries(f));for(const k of ['cotLabel','cotBaseMode','cotBase','cotEmployee','cotEmployer'])delete v[k];const labels=f.getAll('cotLabel'),modes=f.getAll('cotBaseMode'),bases=f.getAll('cotBase'),ers=f.getAll('cotEmployee'),eers=f.getAll('cotEmployer');v.rows=labels.map((label,i)=>({label,baseMode:modes[i],base:bases[i],employeeRate:ers[i],employerRate:eers[i]}));if(v.absenceStart&&v.absenceEnd&&v.absenceEnd<v.absenceStart)throw Error('La fin de l’absence précède son début.');for(const [amount,tax]of[['trip','tripTaxable'],['transportBtp','transportBtpTaxable'],['grandTravel','grandTaxable']])if(Number(v[tax])>Number(v[amount]))throw Error('La part soumise d’un déplacement dépasse son total.');if(Number(v.navigoPercent)>100)throw Error('La part de transport ne peut pas dépasser 100 %.');if(Number(v.mealTaxable)>Number(v.mealTotal))throw Error('La part soumise des paniers dépasse le total payé.');return v;}
variable=function(id){const p=people().find(p=>p.id===id);extendedForm(variableMarkup(p),f=>{const v=readVariableForm(f);if(v.base==='')throw Error('Salaire mensuel à compléter.');grossPreview(v);db.vars[vkey(p)]={...richVar(p),...v,updatedAt:new Date().toISOString()};if(!save())throw Error('Enregistrement impossible.');});$('#form').insertAdjacentHTML('afterbegin',`<div class="notice" aria-live="polite">Brut calculé : <strong id="grossLive"></strong><p id="calculationError" role="alert"></p></div>`);$('#form').oninput=refreshCalculations;$('#form').onchange=refreshCalculations;refreshCalculations();};
function engineInput(v){const rate=v.hourlyRate||'0';const line=(label,h,percent)=>({label,hours:h,rate,multiplier:(1+Number(percent)/100).toFixed(4)});return{...v,bonus:v.bonus,absenceDeduction:PayrollTest.moneyTotal([v.absenceDeduction,v.cpAutoDeduction||0]).toFixed(2),extraGross:PayrollTest.moneyTotal([v.nightPremium,v.sundayPremium,v.holidayPremium,v.cpPaid]).toFixed(2),hoursLines:[line('Heures supplémentaires +25 %',v.extra25,25),line('Heures supplémentaires +50 %',v.extra50,50),line('Heures supplémentaires +100 %',v.extra100,100),line('Heures supplémentaires autre taux',v.extraOther,v.otherPercent),line('Heures complémentaires',v.hcHours,v.hcPercent)],travel:PayrollTest.moneyTotal([v.trip,v.transportBtp,v.grandTravel]).toFixed(2),travelTaxable:PayrollTest.moneyTotal([v.tripTaxable,v.transportBtpTaxable,v.grandTaxable]).toFixed(2),transport:PayrollTest.moneyTotal([v.urbanTransport??PayrollTest.percentageAmount(v.navigoPrice,v.navigoPercent),v.otherExpenses]).toFixed(2)};}
function issues(p,v){let a=[];if(!p.startDate)a.push('Date de début de contrat absente');if(!p.idcc&&!db.companies.find(c=>c.id===company).idcc)a.push('Convention / IDCC à préciser');if(p.contract==='CDD'&&!p.endDate&&!p.cddMinimumEndDate)a.push('Fin ou terme du CDD à préciser');if(p.scheme==='Apprentissage')a.push('Rémunération et exonérations apprentissage à valider');if(Number(v.absenceHours)>0||Number(v.ijss)>0||Number(v.cpDays)>0)a.push('Absences / congés / IJSS à vérifier');if(v.exitDate)a.push('Sortie et indemnités à calculer séparément');if(!v.source)a.push('Justificatif / décompte des heures à renseigner');return a;}
function createDraft(id){const p=people().find(p=>p.id===id),v=richVar(p);if(v.salaryProrationError){toast(v.salaryProrationError);return;}let missing=[];if(v.base==='')missing.push('salaire de base');if(v.taxableNet==='')missing.push('net imposable de test');if(v.socialNet==='')missing.push('net social de test');if(v.pasRate==='')missing.push('taux PAS de test');if(!v.rows.length)missing.push('au moins une ligne de cotisation de test');if([v.extra25,v.extra50,v.extra100,v.extraOther,v.hcHours].some(h=>Number(h)>0)&&!Number(v.hourlyRate))missing.push('taux horaire des majorations');if(missing.length){toast('À compléter : '+missing.join(', ')+'.');return;}try{if(v.leaveAcquisitionError)throw Error(v.leaveAcquisitionError);leaveReady(v);const check=btpDraftCheck(v,period());if(check){variable(id);const target=$('#form').elements[check.field];if(target?.closest('details'))target.closest('details').open=true;$('#formError').textContent=check.message;if(target&&target.type!=='hidden')target.focus();else $('#form').insertAdjacentHTML('afterbegin',`<p class="notice" role="alert">${esc(check.message)}</p>`);return;}const result=PayrollTest.calculate(engineInput(v));const c=db.companies.find(c=>c.id===company);const doc={id:crypto.randomUUID(),company,personId:id,period:period(),paymentDate:CompanyUtils.paymentDate(period()),createdAt:new Date().toISOString(),engine:PayrollTest.version,person:structuredClone(p),employer:structuredClone(c),variables:structuredClone(v),result,issues:issues(p,v)};db.bulletins.push(doc);if(!save()){db.bulletins.pop();return;}view='Bulletins de test';render();showDraft(doc.id);}catch(e){toast(e.message);}}
function chooseDemo(){const ps=people();if(!ps.length){toast('Ajoutez d’abord un salarié de test.');return;}const p=ps.find(p=>p.id===selectedPerson)||ps[0];extendedForm(`<h2>Charger un exemple fictif</h2><p>Un salarié « Exemple bulletin TEST » sera ajouté. Vos fiches et variables existantes seront conservées.</p><p>Cas de test : base 2 000 €, 4 h à +25 %, 2 h à +50 %, 3 h à +100 %, 10 paniers à 12 €, ventilation manuelle et cotisations fictives.</p>`,()=>{const id=crypto.randomUUID(),person={...p,id,name:'Exemple bulletin TEST',job:'Poste fictif',monthlyBase:'2000',hourlyRate:'10',startDate:'2026-01-01',contract:'CDI',scheme:'Aucun',idcc:'TEST — aucune convention validée'};db.people.push(person);const v={...richVar(person),base:'2000',monthlySalary:'2000',baseMode:'Mensuel',navigoPrice:'0',hourlyRate:'10',bonus:'100',extra25:'4',extra50:'2',extra100:'3',mealQty:'10',mealUnit:'12',mealTaxable:'20',trip:'50',tripTaxable:'10',otherExpenses:'30',absenceDeduction:'50',advance:'100',otherDeduction:'10',taxableNet:'1900',socialNet:'1800',pasRate:'5',status:'À vérifier',source:'Jeu fictif de recette — aucune valeur réglementaire',rows:[{label:'Cotisation fictive A',baseMode:'gross',base:'0',employeeRate:'10',employerRate:'20'},{label:'Cotisation fictive B',baseMode:'manual',base:'1000',employeeRate:'2',employerRate:'3'}]};db.vars[vkey(person)]=v;selectedPerson=id;save();});}
const extendedViews=['Préparation paie','Bulletins de test','Entreprise'];
render=function(){if(!extendedViews.includes(view)){normalRender();return;}document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.textContent===view));const ps=people();let html='';if(view==='Entreprise'){const c=db.companies.find(c=>c.id===company);html=head('Le cadre de votre paie.','Identité et paramètres de l’entreprise.',`<button class="btn" onclick="companyEdit()">Modifier l’entreprise</button>`)+`<section class="panel"><h2>${esc(c.name)}</h2><div class="facts"><p>Secteur<br><strong>${esc(c.sector)}</strong></p><p>Convention / IDCC<br><strong>${esc(c.idcc||'À définir')}</strong></p><p>SIRET<br><strong>${esc(c.siret||'À définir')}</strong></p><p>Caisse de congés<br><strong>${esc(c.cibtp||'À définir / non applicable')}</strong></p></div><p>${esc(c.address||'Adresse à compléter')}</p><p class="muted">Paramétrage de test. Les taux et règles réglementaires ne sont pas fournis.</p></section>`;}else if(view==='Préparation paie'){html=head('Les variables qui font la paie.','Contrats, heures, paniers, absences et retenues, avant le bulletin.',`<button class="btn" onclick="csv()">Exporter les variables CSV</button>`)+`<div class="tools"><button class="btn secondary" onclick="chooseDemo()">Charger un exemple fictif</button><button class="btn secondary" onclick="go('Entreprise')">Paramètres entreprise</button></div><section class="panel"><h2>Préparation · ${esc(period())}</h2><p class="muted">Les trois majorations sont séparées. Chaque panier est décrit par quantité, valeur unitaire et part soumise.</p>${ps.length?`<div class="scroll"><table><tr><th>Salarié / contrat</th><th>Base / brut calculé</th><th>HS 25 / 50 / 100</th><th>Paniers / transport urbain</th><th>État</th><th>Actions</th></tr>${ps.map(p=>{const v=richVar(p);return `<tr><td>${esc(p.name)}<small>${esc(personDefaults(p).contract)} · ${esc(personDefaults(p).scheme)}<br>${esc(p.startDate||'Début à préciser')}${p.endDate?' → '+esc(p.endDate):''}</small></td><td>${v.base===''?'À définir':euroFmt(v.base)}<small>Brut : ${autoSummary(v)}</small></td><td>${esc(v.extra25)} / ${esc(v.extra50)} / ${esc(v.extra100)} h</td><td>${esc(v.mealQty)} × ${euroFmt(v.mealUnit)} = ${euroFmt(v.mealTotal)}<small>Transport urbain : ${euroFmt(v.urbanTransport)} (50 %)</small></td><td><span class="badge ${v.status==='Validé'?'':'warn'}">${esc(v.status)}</span></td><td><div class="row-actions"><button class="btn secondary" onclick="variable('${p.id}')">Préparer</button><button class="btn" onclick="createDraft('${p.id}')">Bulletin test</button></div></td></tr>`}).join('')}</table></div>`:'<p>Aucun salarié pour cette entreprise.</p>'}</section><section class="panel" style="margin-top:20px"><h2>Avant un bulletin utilisable</h2><p>Le calcul actuel applique vos montants, assiettes et taux de test. Barèmes légaux, cotisations complètes, exonérations, net fiscal et net social réglementaires restent à construire et à valider. Une validation des variables ne change pas cette limite.</p></section>`;}else{const docs=db.bulletins.filter(d=>d.company===company&&d.period===period());html=head('Vos bulletins de test.','Photographies datées des données et calculs, conservées dans ce navigateur.',`<button class="btn secondary" onclick="go('Préparation paie')">Préparer un bulletin</button>`)+`<section class="panel">${docs.length?`<div class="scroll"><table><tr><th>Salarié</th><th>Créé le</th><th>Brut test</th><th>Net test</th><th></th></tr>${docs.map(d=>`<tr><td>${esc(d.person.name)}<small>TEST · ${esc(d.period)}</small></td><td>${new Date(d.createdAt).toLocaleString('fr-FR')}</td><td>${euroFmt(d.result.gross)}</td><td>${euroFmt(d.result.net)}</td><td><button class="btn secondary" onclick="showDraft('${d.id}')">Ouvrir</button></td></tr>`).join('')}</table></div>`:'<div class="empty">Aucun bulletin de test pour cette période. Préparez les variables puis cliquez sur « Bulletin test ».</div>'}</section>`;}$('#app').innerHTML=html;};
function showDraft(id){const d=db.bulletins.find(b=>b.id===id);if(!d)return;$('#form').innerHTML=`<div class="no-print"><div class="heading"><h2>Bulletin de test</h2><button type="button" class="btn secondary" onclick="document.querySelector('dialog').close()">Fermer</button></div><div class="tools"><button type="button" class="btn" onclick="downloadPDF('${id}')">Télécharger le PDF de test</button><button type="button" class="btn secondary" onclick="printDraft('${id}')">Imprimer</button><button type="button" class="btn secondary" onclick="downloadDraft('${id}')">Télécharger les calculs JSON</button></div></div>${d.issues.length?`<details class="no-print"><summary>Points à vérifier dans la préparation</summary><p>${d.issues.map(esc).join('; ')}</p></details>`:''}${draftMarkup(d)}`;$('#form').onsubmit=e=>e.preventDefault();$('#modal').showModal();}
function contractDetails(p,v){const a=[['Référence',p.contractId],['Nature',personDefaults(p).contract],['Type particulier',p.contractVariant&&p.contractVariant!=='Droit commun'?p.contractVariant:''],['Organisation',p.workOrganization&&p.workOrganization!=='Horaire habituel'?p.workOrganization:''],['Dispositif',personDefaults(p).scheme],['Début',p.startDate],['Ancienneté depuis',p.seniorityDate],['Fin prévue',p.endDate],['Fin réelle',p.actualEndDate],['Période d’essai — fin',p.trialEnd],['Modalité',p.workMode],['Durée hebdomadaire',p.weeklyHours!==undefined&&p.weeklyHours!==''?p.weeklyHours+' h':''],['Durée mensuelle',p.hours!==undefined?p.hours+' h':''],['Salaire de base contractuel',p.monthlyBase!==undefined&&p.monthlyBase!==''?euroFmt(p.monthlyBase):''],['Taux horaire contractuel',p.hourlyRate!==undefined&&p.hourlyRate!==''?euroFmt(p.hourlyRate):''],['Effet du salaire',p.salaryEffective],['HS structurelles',p.structuralHours],['Répartition du travail',p.schedule]];if(p.contract==='CDD')a.push(['Motif de recours au CDD',p.cddReason||'À renseigner'],['Motif de fin CDD',p.cddEndReason],['Précisions de fin',p.cddEndDetails]);if(p.scheme==='Apprentissage'||p.contract==='Apprentissage')a.push(['CFA',p.cfa],['Diplôme préparé',p.diploma],['Année du cycle',p.apprenticeYear],['Taux de rémunération',p.apprenticePercent?p.apprenticePercent+' %':''],['Référence apprentissage',p.apprenticeReference]);return a.filter(([l,x])=>['Référence','Nature','Dispositif','Début'].includes(l)||(x!==undefined&&x!==''));}
function salaryBaseMarkup(d,line){const v=d.variables,b=SalaryBaseLines.calculate(d);if(b)return line('Salaire de base mensuel',b.reference.toFixed(2)+' h',euroFmt(b.rate),b.full)+line(b.label,'−'+b.hours.toFixed(2)+' h',euroFmt(b.rate),-b.deduction);return line(v.baseMode==='Horaire'?'Salaire de base — heures rémunérées':v.salaryProrataApplied?'Salaire de base — entrée / sortie':'Salaire de base test',v.baseMode==='Horaire'?v.hours+' h':v.salaryProrataApplied?v.salaryContractHours+' h / '+v.salaryMonthHours+' h':'',v.baseMode==='Horaire'?euroFmt(v.hourlyRate):v.salaryProrataApplied?'Prorata horaire réel':'',d.result.base);}
function draftMarkup(d){const r=d.result,v=d.variables,p=d.person,c=d.employer;const line=(label,base,rate,amount,employer='')=>`<tr><td>${esc(label)}</td><td>${esc(base)}</td><td>${esc(rate)}</td><td>${amount===''?'':euroFmt(amount)}</td><td>${employer===''?'':euroFmt(employer)}</td></tr>`;return `<article class="payslip"><div class="test-banner">TEST — NON UTILISABLE POUR UNE PAIE RÉELLE</div><header class="pro-slip-header"><div><span class="pro-eyebrow">MA PAYE.0 · DOCUMENT DE TEST</span><h1>BULLETIN DE PAIE</h1></div><div class="pro-period"><span>Période</span><strong>${esc(d.period)}</strong><span>Paiement : ${esc(d.paymentDate?CompanyUtils.formatDate(d.paymentDate):'À renseigner')}</span></div></header><div class="slip-identities pro-identities"><div class="pro-left"><section class="pro-employer"><h2>EMPLOYEUR</h2><h3>${esc(c.name)}</h3><p>${esc(c.address||'Adresse à renseigner')}<br>SIRET : ${esc(c.siret||'À renseigner')}<br>Code APE : ${esc(c.ape||'À renseigner')}</p>${CompanyAtmp.description(c)?`<p class="atmp-summary">${esc(CompanyAtmp.description(c))}</p>`:''}<div class="pro-convention"><span>CONVENTION COLLECTIVE</span><strong>${esc(Conventions.display(p.idcc||c.idcc)||'À renseigner')}</strong></div></section><section class="pro-contract"><h2>CONTRAT DU SALARIÉ</h2>${contractDetails(p,v).map(([label,value])=>`<div class="contract-line${/Motif|Précisions|Répartition/.test(label)?' contract-wide':''}"><span>${esc(label)}</span><strong>${esc(value||'À renseigner')}</strong></div>`).join('')}</section></div><div class="pro-right"><section class="pro-address"><h2>ADRESSE DU SALARIÉ</h2><p class="address-name">${esc(EmployeeAddress.lines(p).name)}</p>${EmployeeAddress.lines(p).street.map(line=>`<p class="address-line">${esc(line)}</p>`).join('')}<p class="address-locality">${esc(EmployeeAddress.lines(p).locality)}</p></section><section class="pro-person"><h2>INFORMATIONS SALARIÉ</h2><div class="contract-line"><span>Matricule</span><strong>${esc(p.matricule||'À renseigner')}</strong></div><div class="contract-line"><span>Emploi</span><strong>${esc(p.job||'À renseigner')}</strong></div><div class="contract-line"><span>Catégorie</span><strong>${esc(p.category||'À renseigner')}</strong></div><div class="contract-line"><span>Classification</span><strong>${esc(p.classification||'À renseigner')}</strong></div><div class="contract-line"><span>Ancienneté</span><strong>${esc(EmployeeSeniority.describe(p,d.period))}</strong></div></section></div></div><div class="scroll"><table class="slip-table"><thead><tr><th>Rubrique</th><th>Base / quantité</th><th>Taux / coefficient</th><th>Montant / salarié</th><th>Employeur</th></tr></thead><tbody>${salaryBaseMarkup(d,line)}${r.hours.filter(h=>Number(h.hours)>0).map(h=>line(h.label,h.hours+' h',h.rate+' € × '+h.multiplier,h.amount)).join('')}${r.bonus?line('Autres primes brutes','','',r.bonus):''}${r.extraGross?line('Primes spécifiques / maintien ajoutés','','',r.extraGross):''}${r.absence?line('Retenues pour absence / congés','','',-r.absence):''}${line('Prime panier — part soumise',v.mealQty+' paniers','Soumise à cotisations',r.mealTaxable)}${r.travelTaxable?line('Déplacements : part soumise','','',r.travelTaxable):''}${r.advantages?line('Avantage en nature ajouté au brut','','',r.advantages):''}${line('TOTAL BRUT TEST','','',r.gross)}${r.rows.map(row=>line(row.label,row.fixed?'1 salarié':euroFmt(row.base),row.fixed?'Forfait employeur':row.employeeRate+' % / '+row.employerRate+' %',row.employee,row.employer)).join('')}${line('TOTAL COTISATIONS SAISIES','','',r.employee,r.employer)}${line('Prime panier — part non soumise',v.mealQty+' paniers','Part non soumise',Number((r.meal-r.mealTaxable).toFixed(2)))}${v.urbanTransport!==undefined?line('Transport urbain remboursé',v.navigoPrice+' €','50 % × '+(v.transportEligibility??100)+' %',v.urbanTransport):''}${line('TOTAL FRAIS NON SOUMIS (paniers et transport inclus)','','',r.reimburse)}${r.advantages?line('Avantage en nature déduit du net','','',-r.advantages):''}${r.advance?line('Acompte déjà versé','','',-r.advance):''}${r.other?line('Autres retenues nettes','','',-r.other):''}</tbody></table></div><div class="net-block"><div><span>Net avant PAS — test</span><strong>${euroFmt(r.netBefore)}</strong></div><div><span>Net imposable fourni manuellement</span><strong>${euroFmt(r.taxable)}</strong></div><div><span>Net social fourni manuellement</span><strong>${r.social===null?'Non renseigné':euroFmt(r.social)}</strong></div><div><span>PAS de test · ${esc(v.pasRate)} %</span><strong>${euroFmt(r.pas)}</strong></div><div class="final-net"><span>NET À PAYER — SIMULATION</span><strong>${euroFmt(r.net)}</strong></div></div><p><strong>Paramètres et calculs non validés réglementairement.</strong> Aucun bulletin définitif ni DSN n’est émis. Net imposable et net social saisis manuellement ; taux de cotisations fournis par l’utilisateur.</p><div data-leave-summary></div><p class="muted">Créé le ${new Date(d.createdAt).toLocaleString('fr-FR')} · ${esc(d.engine)} · Référence ${esc(d.id)}<br>Photographie des données de test ; cumuls annuels, minima et plafonds réglementaires non calculés. Ce document ne vaut pas bulletin conforme.</p><div class="test-banner">TEST — NE PAS REMETTRE À UN SALARIÉ</div></article>`;}
function printDraft(id){const d=db.bulletins.find(b=>b.id===id);let node=$('#bulletinPrint');if(!node){node=document.createElement('div');node.id='bulletinPrint';document.body.appendChild(node);}node.innerHTML=draftMarkup(d);window.print();}
function downloadPDF(id){const d=db.bulletins.find(b=>b.id===id);download('MA-PAYE-0-TEST-'+d.period+'.pdf',PayrollPDF.build(d),'application/pdf');}
function downloadDraft(id){download('ma-paye-bulletin-test-'+period()+'.json',JSON.stringify(db.bulletins.find(b=>b.id===id),null,2),'application/json');}
